#include <vector>
#include <omp.h>

/* Compute the prefix sum of the vector x into output.
   Use OpenMP to compute in parallel.
   Example:
   input: [1, 7, 4, 6, 6, 2]
   output: [1, 8, 12, 18, 24, 26]
*/
void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int p = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            p = omp_get_num_threads();
        }
    }

    std::vector<double> blockSums(static_cast<std::size_t>(p), 0.0);
    std::vector<double> blockOffsets(static_cast<std::size_t>(p), 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int tcount = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(tcount);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(tcount);

        double running = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            running += x[i];
            output[i] = running;
        }

        blockSums[static_cast<std::size_t>(tid)] = running;

        #pragma omp barrier

        #pragma omp single
        {
            double acc = 0.0;
            for (int t = 0; t < tcount; ++t) {
                blockOffsets[static_cast<std::size_t>(t)] = acc;
                acc += blockSums[static_cast<std::size_t>(t)];
            }
        }

        const double offset = blockOffsets[static_cast<std::size_t>(tid)];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
